  "claims": [
    {
      "claim": "EM574, a macrolide with a desosamine-type amino sugar and a neutral sugar, has an estimated human oral bioavailability of about 2%, based on a mean oral CL/F of 4500 L/h versus hepatic blood flow of 90 L/h.",
      "card_ids": ["C25", "C43"]
    },
    {
      "claim": "EM574 was described as having very low oral bioavailability in humans, with oral clearance about 50-fold higher than human hepatic blood flow.",
      "card_ids": ["C02"]
    },
    {
      "claim": "Additional non-voting records show EM574 oral bioavailability of 2.4–3.3% in rabbits and low oral bioavailability in rats and dogs, supporting a consistently low-F profile across species.",
      "card_ids": ["C72", "C86"]
    },
    {
      "claim": "The query is a macrolide sharing the desosamine-type sugar and macrolactone scaffold with EM574; no closer high-bioavailability context is available, and the query's physicochemical liabilities (MW 746, TPSA 111, low neutral fraction, acetal groups) do not support F >= 20%.",
      "card_ids": ["C02", "C25", "C43", "C72", "C86"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for clarithromycin and erythromycin show that some macrolides can achieve measurable oral exposure, but these are different molecules and do not provide direct evidence for the query; they do not overturn the EM574-based low prediction.",
      "card_ids": ["C121", "C123", "C129", "C143", "C113", "C122", "C148"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C121", "C123", "C129", "C143", "C113", "C122", "C148"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No human PK data are available for the query; transfer from EM574 is indirect and structural differences such as the permethylated neutral sugar and absence of HBD could alter absorption or first-pass metabolism.",
    "First-pass metabolism, intestinal permeability, and efflux of the query were not directly measured.",
    "L3 oral exposure records are for other macrolides (clarithromycin, erythromycin) and not for the query; their relevance is limited by structural differences."
  ],
  "decision_summary": "Predicted low: the closest transferable context, EM574, is a macrolide with very low human oral bioavailability (~2%) and consistently low F in rabbits, rats, and dogs; the query shares the macrolide/desosamine scaffold and has physicochemical liabilities that do not support F >= 20%. L3 oral exposure records for other macrolides do not provide direct query evidence and do not change the prediction."
}

